struct text_vtable { char padding[24]; short adjustment; short zero; void (*draw)(void *); };
struct TextString { char padding[76]; text_vtable *vtable; void Draw() { text_vtable *v = vtable; v->draw((char *)this + v->adjustment); } };
struct entry_vtable { char padding[56]; short adjustment; short zero; void (*draw)(void *); };
struct FEMenuEntry { int entry_num; FEMenuEntry *next; char padding[88]; entry_vtable *vtable; void Draw() { entry_vtable *v = vtable; v->draw((char *)this + v->adjustment); } };
class PanelFile { public: void Draw(int layer); };
class FEGraphicalMenu {
protected:
    char prefix[60];
    int flags;
    FEMenuEntry *entries;
    char gap[188];
public:
    PanelFile panel;
    char suffix[76];
    void Draw()
    {
        FEMenuEntry *tmp = entries;
        while(tmp != 0)
        {
            tmp->Draw();
            tmp = tmp->next;
        }
    }
};
class PanelQuad;
class OptionsMenu : public FEGraphicalMenu
{
    enum { OpStereoEntry = 5, OpMasterEntry = 6, OpEnd = 11 };
    static const int MAX_VOLUME = 10;
    static const int NUM_VOLUME = 5;
    static const int num_switches = OpStereoEntry;
    PanelQuad* levels[NUM_VOLUME][MAX_VOLUME];
    PanelQuad* lights[OpEnd];
    PanelQuad* back;
    float rumbleTimer[4];
    int stereo_op;
    TextString* stereo_text[3];
    TextString* switch_text[num_switches][2];
    TextString* options_text;
    TextString* slevels_text;
    int volumes[NUM_VOLUME];
    FEMenuEntry* options_list[OpEnd];
    bool switches[num_switches];
public:
    void Draw();
};
void OptionsMenu::Draw()
{
    options_text->Draw();
    slevels_text->Draw();
    stereo_text[stereo_op]->Draw();
    for(int i=0; i<num_switches; i++)
        switch_text[i][switches[i]]->Draw();
    panel.Draw(0);
    FEGraphicalMenu::Draw();
}
